appCss:
/* ========================================================
   PEOPLEHCM MOBILE APP STYLES (MODULAR & THEME-AWARE)
   ======================================================== */

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
  font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

html, body {
  height: 100vh;
  height: 100dvh;
  margin: 0;
  padding: 0;
  overflow: hidden;
}

body {
  background-color: var(--bg-page);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  color: var(--text-primary);
  transition: background-color 0.3s ease, color 0.3s ease;
}

/* ========================================================
   STANDARD FILTER SHEET
   Canonical filter presentation — mirrors Claim History.
   Applied by initStandardFilterSheets() in js/app.js.
   ======================================================== */
.standard-filter-sheet {
  align-items: flex-end !important;
  justify-content: center !important;
  padding: 0 !important;
  background: rgba(15, 23, 42, 0.6) !important;
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  z-index: 1200 !important;
}

.standard-filter-sheet.is-open {
  display: flex !important;
  opacity: 1 !important;
  pointer-events: auto !important;
}

#sharedInlineFilterSheet {
  position: absolute !important;
  inset: 0 !important;
  display: none !important;
  opacity: 0 !important;
  pointer-events: none !important;
  border-radius: 44px;
  overflow: hidden;
}

#sharedInlineFilterSheet.is-open {
  display: flex !important;
  opacity: 1 !important;
  pointer-events: auto !important;
}

.standard-filter-panel {
  width: 100% !important;
  max-width: 480px !important;
  max-height: min(88%, calc(100dvh - 24px)) !important;
  display: flex !important;
  flex-direction: column !important;
  overflow-x: hidden !important;
  overflow-y: auto !important;
  background: var(--bg-card) !important;
  border: 1px solid var(--border-subtle) !important;
  border-bottom: 0 !important;
  border-radius: 28px 28px 0 0 !important;
  box-shadow: 0 -10px 30px rgba(0, 0, 0, 0.3) !important;
}

.standard-filter-handle {
  width: 36px;
  height: 4px;
  margin: 12px auto 16px;
  border-radius: 4px;
  background: var(--border-subtle);
  opacity: 0.7;
  flex: 0 0 auto;
}

.standard-filter-header {
  display: flex !important;
  align-items: center !important;
  justify-content: space-between !important;
  gap: 14px;
  padding: 0 20px 16px !important;
  margin: 0 !important;
}

.standard-filter-header h2,
.standard-filter-header h3,
.standard-filter-header .sheet-title,
.standard-filter-header .filter-modal-title {
  margin: 0 !important;
  color: var(--text-primary) !important;
  font-size: 18px !important;
  font-weight: 800 !important;
  letter-spacing: -0.15px !important;
}

.standard-filter-subtitle,
.standard-filter-header > p,
.standard-filter-header > small {
  display: none !important;
}

.standard-filter-header-actions {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  flex: 0 0 auto;
}

.standard-filter-close {
  width: 34px !important;
  height: 34px !important;
  padding: 0 !important;
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--border-subtle) !important;
  border-radius: 50% !important;
  background: var(--bg-input) !important;
  color: var(--text-muted) !important;
  font-size: 14px !important;
  cursor: pointer;
}

.standard-filter-panel label {
  display: block !important;
  margin-bottom: 8px !important;
  color: var(--purple-text) !important;
  font-size: 13px !important;
  font-weight: 700 !important;
  text-transform: none !important;
  letter-spacing: normal !important;
}

.standard-filter-panel input:not([type="checkbox"]):not([type="radio"]),
.standard-filter-panel select,
.standard-filter-panel textarea {
  width: 100% !important;
  min-height: 48px !important;
  padding: 12px 16px !important;
  border: 1px solid var(--border-subtle) !important;
  border-radius: 16px !important;
  background: var(--bg-input) !important;
  color: var(--text-primary) !important;
  font-family: inherit !important;
  font-size: 13.5px !important;
  font-weight: 700 !important;
  outline: none !important;
}

.standard-filter-panel input:focus,
.standard-filter-panel select:focus,
.standard-filter-panel textarea:focus {
  border-color: var(--purple-primary) !important;
  box-shadow: 0 0 0 3px var(--purple-subtle) !important;
}

.standard-filter-reset {
  display: inline-flex !important;
  align-items: center !important;
  gap: 6px !important;
  padding: 7px 14px !important;
  border: 1px solid var(--border-subtle) !important;
  border-radius: 20px !important;
  background: var(--bg-input) !important;
  color: var(--text-primary) !important;
  font-family: inherit !important;
  font-size: 12px !important;
  font-weight: 700 !important;
  white-space: nowrap !important;
  cursor: pointer;
}

.standard-filter-apply {
  width: 100% !important;
  min-height: 48px !important;
  padding: 15px !important;
  border: 0 !important;
  border-radius: 18px !important;
  background: linear-gradient(135deg, #7c3aed, #6366f1) !important;
  color: #ffffff !important;
  font-family: inherit !important;
  font-size: 15px !important;
  font-weight: 800 !important;
  box-shadow: 0 8px 20px rgba(124, 58, 237, 0.35) !important;
  cursor: pointer;
}

.standard-filter-apply > i,
.standard-filter-apply > svg {
  display: none !important;
}

.standard-filter-reset:active,
.standard-filter-close:active,
.standard-filter-apply:active {
  transform: scale(0.98);
}

.standard-filter-inline-body {
  padding: 4px 20px 20px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}

.standard-filter-inline-body > #filterBodyContainer {
  display: flex !important;
  flex-direction: column !important;
  gap: 16px !important;
  padding: 0 !important;
}

.standard-filter-footer {
  padding: 4px 20px 24px;
  flex: 0 0 auto;
}

.standard-filter-legacy-action,
.standard-filter-unused {
  display: none !important;
}

.standard-filter-inline-trigger {
  cursor: pointer;
}

/* ========================================================
   CUSTOM WEB ELEMENTS DISPLAY RULES
   ======================================================== */
preview-top-bar {
  display: flex;
  justify-content: center;
  width: 100%;
}

phone-status-bar,
phone-bottom-nav,
app-header {
  display: block;
  width: 100%;
}

phone-hero-bg,
left-profile-drawer,
notification-sheet,
indicators-sheet,
company-updates-sheet {
  display: contents;
}

/* Top Theme Switcher Bar */
.theme-switch-bar {
  margin-bottom: 14px;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: 6px;
  background: var(--bg-card);
  border: 1px solid var(--border-card);
  padding: 5px 10px;
  border-radius: 20px;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  max-width: 440px;
}

.mode-btn {
  padding: 5px 10px;
  border-radius: 10px;
  font-size: 11.5px;
  font-weight: 600;
  text-decoration: none;
  color: var(--text-muted);
  border: none;
  background: transparent;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
  transition: all 0.2s ease;
}

.mode-btn.active {
  background: #7c3aed;
  color: #ffffff;
  box-shadow: 0 2px 8px rgba(124, 58, 237, 0.35);
}

.bar-divider {
  width: 1px;
  height: 16px;
  background: var(--border-subtle);
  margin: 0 2px;
}

/* Mobile Frame */
.phone-container {
  width: 100%;
  max-width: 420px;
  height: min(900px, calc(100vh - 20px));
  height: min(900px, calc(100dvh - 20px));
  background: var(--bg-phone);
  border-radius: 44px;
  overflow: hidden;
  box-shadow: var(--shadow-phone);
  position: relative;
  display: flex;
  flex-direction: column;
  transition: background 0.3s ease, box-shadow 0.3s ease;
}

/* Royal Purple Constellation Hero Background */
.hero-bg {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 520px;
  background:
    url('hero-purple-mesh.jpg') center top / cover no-repeat,
    radial-gradient(circle at 85% 12%, rgba(168, 85, 247, 0.45) 0%, transparent 50%),
    linear-gradient(178deg, #4c1d95 0%, #6d28d9 35%, #7c3aed 70%, #5b21b6 90%, var(--bg-phone) 100%);
  pointer-events: none;
  z-index: 1;
  overflow: hidden;
}

[data-theme="dark"] .hero-bg {
  height: 520px;
  background:
    url('hero-purple-mesh.jpg') center top / cover no-repeat,
    radial-gradient(circle at 85% 12%, rgba(168, 85, 247, 0.45) 0%, transparent 50%),
    linear-gradient(178deg, #2e1065 0%, #4c1d95 35%, #6d28d9 70%, #7c3aed 90%, var(--bg-phone) 100%);
}

[data-theme="light"] .hero-bg {
  height: 520px;
  background:
    url('hero-purple-mesh.jpg') center top / cover no-repeat,
    radial-gradient(circle at 85% 12%, rgba(168, 85, 247, 0.45) 0%, transparent 50%),
    linear-gradient(178deg, #4c1d95 0%, #6d28d9 35%, #7c3aed 70%, #5b21b6 90%, var(--bg-phone) 100%);
}

.hero-bg svg {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
}

/* Status Bar */
.status-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 14px 28px 8px;
  font-size: 14px;
  font-weight: 700;
  color: var(--text-hero);
  position: relative;
  z-index: 10;
}

.status-icons {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--text-hero);
}

/* App Header */
.app-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 20px 12px;
  position: relative;
  z-index: 10;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 12px;
}

.burger-btn {
  width: 36px;
  height: 36px;
  border-radius: 11px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.22);
  color: #ffffff;
  cursor: pointer;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: all 0.18s ease;
}

.burger-btn:hover {
  background: rgba(255, 255, 255, 0.22);
  border-color: rgba(192, 132, 252, 0.5);
  transform: scale(1.04);
}

.burger-btn:active {
  transform: scale(0.95);
}

.logo-container {
  display: flex;
  align-items: center;
  gap: 10px;
}

.logo-icon {
  width: 32px;
  height: 32px;
}

.logo-text h1 {
  font-size: 18px;
  font-weight: 800;
  letter-spacing: -0.3px;
  line-height: 1.1;
  color: #ffffff;
}

.logo-text span {
  font-size: 10px;
  color: rgba(255, 255, 255, 0.7);
  font-weight: 600;
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.header-bell-btn {
  position: relative;
  width: 36px;
  height: 36px;
  border-radius: 11px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.22);
  color: #ffffff;
  cursor: pointer;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  transition: all 0.18s ease;
}

.header-bell-btn:hover {
  background: rgba(255, 255, 255, 0.22);
  border-color: rgba(192, 132, 252, 0.5);
  transform: scale(1.04);
}

.bell-badge-yellow {
  position: absolute;
  top: -3px;
  right: -3px;
  background: #f59e0b;
  color: #0f172a;
  font-size: 10px;
  font-weight: 800;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.25);
}

.profile-wrap {
  display: flex;
  align-items: center;
}

.profile-img {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid rgba(255, 255, 255, 0.88);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
}

/* Main Scrollable Content */
.main-content {
  flex: 1;
  overflow-y: auto;
  padding: 6px 18px 90px;
  position: relative;
  z-index: 5;
  scrollbar-width: none;
}

.main-content::-webkit-scrollbar {
  display: none;
}

/* Greeting Header Box */
.greeting-header-box {
  margin-bottom: 20px;
  padding-top: 4px;
}

.greeting-title {
  font-size: 22px;
  font-weight: 800;
  color: var(--text-hero);
  letter-spacing: -0.3px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.greeting-sub {
  font-size: 13.5px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.8);
  margin-top: 4px;
}

/* Greeting Segmented Tab Switch (My Work / My Team) */
.greeting-tab-switch {
  display: flex;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 9999px;
  padding: 4px;
  margin-top: 14px;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

[data-theme="light"] .greeting-tab-switch {
  background: rgba(255, 255, 255, 0.35);
  border-color: rgba(255, 255, 255, 0.5);
}

.greeting-tab {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 9999px;
  font-size: 13px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.85);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all 0.2s ease;
  font-family: inherit;
  text-decoration: none;
}

[data-theme="light"] .greeting-tab {
  color: #ffffff;
}

.greeting-tab.active {
  background: linear-gradient(135deg, #7c3aed, #8b5cf6);
  color: #ffffff;
  box-shadow: 0 4px 12px rgba(124, 58, 237, 0.35);
}

.greeting-tab .tab-count-badge {
  background: #f59e0b;
  color: #0f172a;
  font-size: 11px;
  font-weight: 800;
  padding: 1px 7px;
  border-radius: 9999px;
  line-height: 1.3;
}

/* Common Section Header */
.section-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
}

.section-title {
  font-size: 15px;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.2px;
}

.main-content > .greeting-header-box + .section-header .section-title,
.shortcuts-header .section-title,
.section-header.hero-section .section-title {
  color: #ffffff;
}

.explore-header {
  margin-top: 38px !important;
  margin-bottom: 14px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.explore-title {
  font-size: 15px;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.2px;
}

.recently-used-section .section-title {
  color: #ffffff !important;
  font-weight: 800;
  letter-spacing: -0.2px;
}

.recently-used-section .section-link {
  color: rgba(255, 255, 255, 0.85) !important;
  font-size: 12.5px;
  font-weight: 700;
  text-decoration: none;
}

[data-theme="light"] .explore-header .explore-title {
  color: #0f172a;
  font-weight: 800;
  letter-spacing: -0.2px;
  transition: color 0.25s ease, text-shadow 0.25s ease;
}

[data-theme="dark"] .explore-header .explore-title {
  color: #ffffff;
  font-weight: 800;
  letter-spacing: -0.2px;
  transition: color 0.25s ease, text-shadow 0.25s ease;
}

.section-action {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 12.5px;
  font-weight: 700;
  color: var(--purple-text);
  text-decoration: none;
  cursor: pointer;
  transition: color 0.15s ease;
}

.section-action:hover {
  color: var(--purple-hover);
}

.section-link {
  font-size: 12px;
  font-weight: 700;
  color: #c084fc;
  text-decoration: none;
  cursor: pointer;
  transition: color 0.15s ease;
}

[data-theme="light"] .section-link {
  color: #7c3aed;
}

.section-link:hover {
  text-decoration: underline;
}

/* ========================================================
   1. MY SHORTCUTS (3-COLUMN X 2-ROW BENTO GRID)
   ======================================================== */
.shortcuts-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-bottom: 22px;
}

.shortcut-card {
  background: var(--bg-card);
  border: 1px solid var(--border-card);
  border-radius: 16px;
  padding: 11px 9px 10px;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  text-decoration: none;
  position: relative;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  box-shadow: var(--shadow-card);
  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);
  cursor: pointer;
  min-height: 104px;
}

.shortcut-card:hover {
  background: var(--bg-card-hover);
  border-color: var(--border-focus);
  transform: translateY(-2px);
  box-shadow: var(--shadow-card-hover);
}

.shortcut-top-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  margin-bottom: 8px;
}

.shortcut-star {
  font-size: 10px;
  color: #38bdf8;
  line-height: 1;
}

.shortcut-icon-box {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  flex-shrink: 0;
}

.shortcut-icon-box.purple {
  background: rgba(168, 85, 247, 0.18);
  color: #c084fc;
  border: 1px solid rgba(168, 85, 247, 0.3);
}

.shortcut-icon-box.green {
  background: rgba(16, 185, 129, 0.18);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.3);
}

.shortcut-icon-box.blue {
  background: rgba(59, 130, 246, 0.18);
  color: #60a5fa;
  border: 1px solid rgba(59, 130, 246, 0.3);
}

.shortcut-icon-box.amber {
  background: rgba(245, 158, 11, 0.18);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.3);
}

.shortcut-icon-box.rose {
  background: rgba(244, 63, 94, 0.18);
  color: #fb7185;
  border: 1px solid rgba(244, 63, 94, 0.3);
}

.shortcut-icon-box.cyan {
  background: rgba(6, 182, 212, 0.18);
  color: #22d3ee;
  border: 1px solid rgba(6, 182, 212, 0.3);
}

.shortcut-info {
  width: 100%;
  margin-top: 0;
}

.shortcut-info h4 {
  font-size: 12.5px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
  margin: 0 0 3px 0;
}

.shortcut-info p {
  font-size: 9.5px;
  color: var(--text-muted);
  line-height: 1.25;
  margin: 0;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* ========================================================
   2. RECENTLY USED CAPSULE PILLS
   ======================================================== */
.recently-used-section,
.recently-used-sec {
  margin-bottom: 22px;
}

.recent-label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.75);
  margin-bottom: 8px;
  letter-spacing: 0.3px;
}

.recent-pills,
.recent-pills-row {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  scrollbar-width: none;
  padding-bottom: 2px;
}

.recent-pills::-webkit-scrollbar,
.recent-pills-row::-webkit-scrollbar {
  display: none;
}

.recent-pill {
  background: var(--bg-pill);
  border: 1px solid var(--border-card);
  border-radius: 9999px;
  padding: 6px 14px 6px 8px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12.5px;
  font-weight: 600;
  color: var(--text-secondary);
  text-decoration: none;
  white-space: nowrap;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow: var(--shadow-pill);
  transition: all 0.15s ease;
  cursor: pointer;
}

.recent-pill:hover {
  background: var(--bg-pill-hover);
  border-color: var(--border-focus);
  color: var(--text-primary);
  transform: translateY(-1px);
}

[data-theme="light"] .recent-pill {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  color: #1e293b;
  font-weight: 600;
  box-shadow: 0 2px 8px rgba(15, 23, 42, 0.05);
}

[data-theme="light"] .recent-pill:hover {
  background: #f8fafc;
  border-color: #cbd5e1;
  color: #0f172a;
}

.recent-pill-icon {
  width: 24px;
  height: 24px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
}

.recent-pill-icon.green {
  background: var(--tag-green-bg);
  color: var(--tag-green-text);
}

.recent-pill-icon.blue {
  background: var(--tag-blue-bg);
  color: var(--tag-blue-text);
}

.recent-pill-icon.purple {
  background: var(--purple-subtle);
  color: var(--purple-text);
}

/* Micro-dots for Recently Used pills */
.pill-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}

.pill-dot.green {
  background: #10b981;
  box-shadow: 0 0 6px rgba(16, 185, 129, 0.4);
}

.pill-dot.blue.square {
  background: #3b82f6;
  border-radius: 2px;
  box-shadow: 0 0 6px rgba(59, 130, 246, 0.4);
}

.pill-dot.purple.clock {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: rgba(168, 85, 247, 0.2);
  color: #c084fc;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.explore-footer-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 13px 14px;
  color: #c084fc;
  font-size: 13px;
  font-weight: 700;
  border-top: 1px solid var(--border-divider);
  cursor: pointer;
  background: rgba(168, 85, 247, 0.04);
  transition: all 0.15s ease;
}

[data-theme="light"] .explore-footer-btn {
  color: #7c3aed;
  background: rgba(124, 58, 237, 0.04);
}

.explore-footer-btn:hover {
  background: rgba(168, 85, 247, 0.12);
}

/* ========================================================
   3. EXPLORE PEOPLEHCM (MODULE ROWS)
   ======================================================== */
.explore-list {
  background: var(--bg-card);
  border: 1px solid var(--border-card);
  border-radius: 20px;
  overflow: hidden;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  box-shadow: var(--shadow-card);
  margin-bottom: 24px;
}

.explore-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 14px;
  border-bottom: 1px solid var(--border-divider);
  cursor: pointer;
  transition: background 0.15s ease;
  text-decoration: none;
}

.explore-row:last-child {
  border-bottom: none;
}

.explore-row:hover {
  background: var(--bg-card-hover);
}

.explore-left {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.explore-icon-box {
  width: 36px;
  height: 36px;
  border-radius: 11px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  flex-shrink: 0;
}

.explore-icon-box.purple {
  background: var(--purple-subtle);
  color: var(--purple-text);
}

.explore-icon-box.green {
  background: var(--tag-green-bg);
  color: var(--tag-green-text);
}

.explore-icon-box.amber {
  background: var(--tag-amber-bg);
  color: var(--tag-amber-text);
}

.explore-icon-box.violet {
  background: var(--tag-violet-bg);
  color: var(--tag-violet-text);
}

.explore-icon-box.blue {
  background: var(--tag-blue-bg);
  color: var(--tag-blue-text);
}

.explore-icon-box.teal {
  background: var(--tag-teal-bg);
  color: var(--tag-teal-text);
}

.explore-text {
  min-width: 0;
}

.explore-text h4 {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
}

.explore-text p {
  font-size: 10.5px;
  color: var(--text-muted);
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.explore-chevron {
  color: var(--text-caption);
  font-size: 16px;
  font-weight: 700;
  padding-left: 6px;
  transition: transform 0.15s ease, color 0.15s ease;
}

.explore-row:hover .explore-chevron {
  color: var(--purple-text);
  transform: translateX(2px);
}

/* ========================================================
   BOTTOM NAVIGATION BAR
   ======================================================== */
.bottom-nav {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 78px;
  background: var(--bg-bottom-nav);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-top: 1px solid var(--border-bottom-nav);
  display: flex;
  justify-content: space-around;
  align-items: center;
  padding: 0 10px 14px;
  z-index: 100;
}

.nav-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  color: var(--nav-item-inactive);
  font-size: 10.5px;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  width: 54px;
  transition: color 0.15s ease;
}

.nav-item.active {
  color: var(--nav-item-active);
}

.nav-icon {
  font-size: 20px;
  position: relative;
}

.nav-badge-red {
  position: absolute;
  top: -2px;
  right: -6px;
  background: #ef4444;
  color: #ffffff;
  font-size: 9px;
  font-weight: 800;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1.5px solid var(--bg-bottom-nav);
}

/* Center Elevated FAB */
.fab-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: linear-gradient(135deg, #8b5cf6, #6d28d9);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  box-shadow: 0 6px 20px rgba(124, 58, 237, 0.45);
  border: none;
  cursor: pointer;
  margin-top: -16px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.fab-btn.active {
  box-shadow: 0 0 0 3.5px rgba(192, 132, 252, 0.5), 0 8px 24px rgba(124, 58, 237, 0.6);
  transform: translateY(-2px);
}

.fab-btn:active {
  transform: scale(0.92);
}

.home-bar {
  position: absolute;
  bottom: 6px;
  left: 50%;
  transform: translateX(-50%);
  width: 130px;
  height: 4px;
  background: #94a3b8;
  border-radius: 10px;
  opacity: 0.6;
}

/* ========================================================
   LEFT PROFILE MENU DRAWER CARD
   ======================================================== */
.profile-drawer-overlay,
.drawer-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg-overlay);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 100;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
}

.profile-drawer-overlay.active,
.drawer-overlay.active {
  opacity: 1;
  pointer-events: auto;
}

.profile-drawer-card,
.drawer-card {
  position: absolute;
  top: 0;
  left: 0;
  bottom: 0;
  width: 292px;
  max-width: 82%;
  background: var(--bg-drawer);
  border-right: 1.5px solid var(--border-card);
  box-shadow: var(--shadow-drawer);
  border-radius: 0 26px 26px 0;
  padding: 24px 18px 24px;
  display: flex;
  flex-direction: column;
