  z-index: 101;
  overflow-y: auto;
}

.profile-drawer-overlay.active .profile-drawer-card,
.drawer-overlay.active .drawer-card,
.profile-drawer-overlay.active .drawer-card,
.drawer-overlay.active .profile-drawer-card {
  transform: translateX(0);
}

.profile-drawer-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
}

.drawer-pill-tag {
  font-size: 11px;
  font-weight: 700;
  color: var(--purple-text);
  background: var(--purple-subtle);
  border: 1px solid var(--purple-border);
  padding: 3px 10px;
  border-radius: 12px;
  letter-spacing: 0.2px;
}

.drawer-close-btn {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--bg-input);
  border: 1px solid var(--border-subtle);
  color: var(--text-secondary);
  font-size: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s ease;
}

.drawer-close-btn:hover {
  background: var(--border-subtle);
  color: var(--text-primary);
  transform: scale(1.05);
}

.drawer-user-box {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}

.drawer-avatar-wrap {
  position: relative;
  width: 52px;
  height: 52px;
  flex-shrink: 0;
}

.drawer-avatar-img {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid var(--purple-primary);
  box-shadow: 0 0 12px rgba(124, 58, 237, 0.3);
}

.drawer-avatar-badge {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 13px;
  height: 13px;
  background: #10b981;
  border: 2px solid var(--bg-phone);
  border-radius: 50%;
}

.drawer-user-info {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.drawer-user-name {
  font-size: 16px;
  font-weight: 800;
  color: var(--text-primary);
  line-height: 1.2;
}

.drawer-user-role {
  font-size: 11.5px;
  color: var(--purple-text);
  font-weight: 600;
  margin-top: 2px;
}

.drawer-user-email {
  font-size: 10px;
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin-top: 1px;
}

.drawer-badge-row {
  display: flex;
  gap: 6px;
  margin-bottom: 14px;
}

.drawer-dept-badge,
.drawer-employee-id,
.employee-id-standard {
  display: block;
  margin: 2px 0 4px;
  color: var(--text-muted);
  font-family: monospace, sans-serif;
  font-size: 11.5px;
  font-weight: 700;
  opacity: .8;
}

.drawer-id-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 8px;
  background: var(--bg-input);
  border: 1px solid var(--border-subtle);
  color: var(--text-secondary);
}

.drawer-divider {
  height: 1px;
  background: var(--border-divider);
  margin: 8px 0 12px;
}

.drawer-nav-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1;
}

.drawer-menu-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 14px;
  text-decoration: none;
  color: var(--text-primary);
  background: var(--drawer-item-bg);
  border: 1px solid transparent;
  transition: all 0.18s ease;
  cursor: pointer;
}

.drawer-menu-item:hover {
  background: var(--drawer-item-hover);
  border-color: var(--border-card);
  transform: translateX(3px);
}

.drawer-menu-item.active {
  background: var(--drawer-item-active);
  border-color: var(--purple-border);
  color: var(--purple-text);
}

.drawer-menu-icon {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.drawer-menu-text {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.drawer-menu-label {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
}

.drawer-menu-desc {
  font-size: 10px;
  color: var(--text-muted);
}

.drawer-menu-arrow {
  font-size: 16px;
  color: var(--text-caption);
  font-weight: 600;
}

.drawer-signout-btn {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 14px;
  background: rgba(239, 68, 68, 0.12);
  border: 1px solid rgba(239, 68, 68, 0.28);
  color: #ef4444;
  text-decoration: none;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.18s ease;
  margin-top: 8px;
}

.drawer-signout-btn:hover {
  background: rgba(239, 68, 68, 0.2);
  border-color: rgba(239, 68, 68, 0.5);
  transform: translateX(3px);
}

.drawer-signout-icon {
  display: flex;
  align-items: center;
  justify-content: center;
}

.drawer-footer {
  margin-top: 12px;
  text-align: center;
}

.drawer-footer span {
  font-size: 9.5px;
  color: var(--text-caption);
  font-weight: 600;
  letter-spacing: 0.3px;
}

/* ========================================================
   NOTIFICATION (FOR YOU) BOTTOM SHEET DRAWER
   ======================================================== */
.indicators-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg-overlay);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  z-index: 100;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
  display: flex;
  align-items: flex-end;
}

.indicators-overlay.active {
  opacity: 1;
  pointer-events: auto;
}

.indicators-overlay.instant,
.indicators-overlay.instant .indicators-sheet {
  transition: none !important;
}

.indicators-sheet {
  width: 100%;
  min-height: 480px;
  max-height: 82%;
  background-color: #ffffff;
  background: var(--bg-sheet);
  border-top: 1.5px solid var(--border-card);
  border-radius: 28px 28px 0 0;
  padding: 14px 18px 30px;
  box-shadow: var(--shadow-sheet);
  display: flex;
  flex-direction: column;
  transform: translateY(100%);
  transition: transform 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

[data-theme="dark"] .indicators-sheet {
  background-color: #15132d;
  background: linear-gradient(180deg, #181534 0%, #0d0e1c 100%);
}

.indicators-overlay.active .indicators-sheet {
  transform: translateY(0);
}

/* Favourite Bottom Sheet Drawer */
.fav-sheet-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(9, 10, 22, 0.65);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  z-index: 105;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.25s ease;
  display: flex;
  align-items: flex-end;
}

.fav-sheet-overlay.active {
  opacity: 1;
  pointer-events: auto;
}

.fav-sheet-content {
  width: 100%;
  max-height: 82%;
  background: var(--bg-sheet);
  border-top: 1.5px solid rgba(168, 85, 247, 0.3);
  border-radius: 28px 28px 0 0;
  padding: 14px 18px 34px;
  box-shadow: 0 -12px 36px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  transform: translateY(100%);
  transition: transform 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  box-sizing: border-box;
}

[data-theme="dark"] .fav-sheet-content {
  background: linear-gradient(180deg, #1d193d 0%, #0d0e1c 100%);
}

.fav-sheet-overlay.active .fav-sheet-content {
  transform: translateY(0);
}

.fav-sheet-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--border-subtle);
}

.fav-edit-btn {
  background: rgba(168, 85, 247, 0.18);
  border: 1px solid rgba(168, 85, 247, 0.35);
  color: #c084fc;
  padding: 5px 12px;
  border-radius: 16px;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
}

.fav-grid-view {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  padding: 4px 0 10px;
}

.fav-grid-item {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: 16px;
  padding: 14px 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
  text-align: center;
}

.fav-grid-item:hover {
  background: var(--bg-card-hover);
  border-color: rgba(168, 85, 247, 0.4);
  transform: translateY(-2px);
}

.fav-grid-icon-box {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
}

.fav-grid-label {
  font-size: 11.5px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
}

.sheet-handle {
  width: 44px;
  height: 4px;
  background: var(--text-caption);
  border-radius: 10px;
  align-self: center;
  margin-bottom: 12px;
}

.sheet-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 14px;
}

.sheet-title h3 {
  font-size: 17px;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.2px;
}

.sheet-title p {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 500;
}

.sheet-close-btn {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--bg-input);
  border: 1px solid var(--border-subtle);
  color: var(--text-secondary);
  font-size: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.15s ease;
}

.sheet-close-btn:hover {
  background: var(--border-subtle);
  color: var(--text-primary);
}

