[data-theme="dark"] .sheet-scope-pill.active {
  background: rgba(124, 58, 237, 0.28);
  color: #c084fc;
  border: 1px solid rgba(192, 132, 252, 0.3);
}

.scope-count-badge {
  font-size: 9.5px;
