/* ========================================================
   UNIVERSAL THEME-ADAPTIVE FILTER BAR & BOTTOM SHEET MODAL
   ======================================================== */
[data-theme="light"],
html[data-theme="light"] {
  --filter-bar-bg: #ffffff;
  --filter-bar-border: #e2e8f0;
  --filter-bar-label-color: #6d28d9;
  --filter-bar-value-color: #0f172a;
  --filter-btn-bg: #f8fafc;
  --filter-btn-color: #475569;
  --filter-btn-border: #cbd5e1;

  --modal-sheet-bg: #ffffff;
  --modal-sheet-color: #0f172a;
  --modal-sheet-border: #e2e8f0;
  --modal-title-color: #0f172a;
  --modal-reset-bg: #f1f5f9;
  --modal-reset-color: #0f172a;
  --modal-reset-border: #cbd5e1;
  --modal-label-color: #6d28d9;
  --modal-input-bg: #f8fafc;
  --modal-input-color: #0f172a;
  --modal-input-border: #cbd5e1;
  --modal-option-bg: #ffffff;
  --modal-option-color: #0f172a;
}

[data-theme="dark"],
html[data-theme="dark"] {
  --filter-bar-bg: #161233;
  --filter-bar-border: rgba(255, 255, 255, 0.14);
  --filter-bar-label-color: #a78bfa;
  --filter-bar-value-color: #ffffff;
  --filter-btn-bg: rgba(255, 255, 255, 0.08);
  --filter-btn-color: #ffffff;
  --filter-btn-border: rgba(255, 255, 255, 0.18);

  --modal-sheet-bg: #161233;
  --modal-sheet-color: #ffffff;
  --modal-sheet-border: rgba(255, 255, 255, 0.15);
  --modal-title-color: #ffffff;
  --modal-reset-bg: rgba(255, 255, 255, 0.12);
  --modal-reset-color: #ffffff;
  --modal-reset-border: rgba(255, 255, 255, 0.2);
  --modal-label-color: #a78bfa;
  --modal-input-bg: rgba(255, 255, 255, 0.08);
  --modal-input-color: #ffffff;
  --modal-input-border: rgba(255, 255, 255, 0.18);
  --modal-option-bg: #161233;
  --modal-option-color: #ffffff;
}

/* Global Component Theme Applications */
