}

.team-pending-approval-action:active {
  transform: scale(0.985);
}

.team-pending-approval-action:focus-visible {
  outline: 2px solid #f59e0b;
  outline-offset: 3px;
}

.team-pending-approval-icon {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  background: #f59e0b;
  color: #ffffff;
  font-size: 18px;
  box-shadow: 0 4px 10px rgba(245, 158, 11, 0.3);
}

.team-pending-approval-copy {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.team-pending-approval-title {
  color: var(--text-primary);
  font-size: 14px;
