/* Global Pending Approval Action Buttons (Standard across Attendance & Claims) */
.pending-action-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
}
.action-btn-approve {
  padding: 9.5px 2px;
  border-radius: 12px;
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
  color: #ffffff;
  font-weight: 800;
  font-size: 11.5px;
  border: none;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  box-shadow: 0 3px 10px rgba(16, 185, 129, 0.25);
  transition: all 0.2s ease;
  font-family: inherit;
}
.action-btn-approve:active { transform: scale(0.95); }

.action-btn-resubmit {
  padding: 9.5px 2px;
  border-radius: 12px;
  background: rgba(59, 130, 246, 0.12);
  border: 1px solid rgba(59, 130, 246, 0.3);
  color: #2563eb;
  font-weight: 800;
  font-size: 11.5px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  transition: all 0.2s ease;
  font-family: inherit;
}
html[data-theme="dark"] .action-btn-resubmit,
[data-theme="dark"] .action-btn-resubmit {
  background: rgba(59, 130, 246, 0.18);
  border-color: rgba(96, 165, 250, 0.35);
  color: #93c5fd;
}
.action-btn-resubmit:active { transform: scale(0.95); }

.action-btn-reject {
  padding: 9.5px 2px;
  border-radius: 12px;
  background: rgba(244, 63, 94, 0.12);
  border: 1px solid rgba(244, 63, 94, 0.3);
  color: #e11d48;
  font-weight: 800;
  font-size: 11.5px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  transition: all 0.2s ease;
  font-family: inherit;
}
html[data-theme="dark"] .action-btn-reject,
[data-theme="dark"] .action-btn-reject {
  background: rgba(244, 63, 94, 0.18);
  border-color: rgba(251, 113, 133, 0.35);
  color: #fca5a5;
